{s:2,k:'bookfig',term:"Figure: the energy balance",title:"The plant's energy balance",view:[40.0, 250.0, 640.0, 190.0],say:'At the bottom, the energy balance. Ten kilowatts come in at the evaporator. The absorber and the condenser both give heat to the cooling water: twenty-six point seven kilowatts.',cues:{s1:'At the bottom',s2:'Ten kilowatts come',s3:'The absorber and',s4:'both give heat',cap:'both give heat'},steps:4,cap:'The cooling water takes the generator heat plus the cooling load.',fig:{"vb": [0.0, 0.0, 720.0, 436.0], "defs": "<defs><marker id=\"ar-f6-8-1b-n\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--accent)\" /></marker><marker id=\"ar-f6-8-1b-m\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--line2)\" /></marker><marker id=\"ar-f6-8-1b-l\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--live)\" /></marker><marker id=\"ar-f6-8-1b-x\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--next)\" /></marker></defs>", "items": [[60.0, "<rect x=\"60.0\" y=\"260.0\" width=\"170.0\" height=\"70.0\" rx=\"8\" style=\"fill:var(--next-soft);stroke:var(--next);stroke-width:2\" />", 1], [470.0, "<rect x=\"470.0\" y=\"260.0\" width=\"170.0\" height=\"70.0\" rx=\"8\" style=\"fill:var(--accent-soft);stroke:var(--accent);stroke-width:2\" />", 1], [145.0, "<text x=\"145.0\" y=\"290.8\" font-size=\"14\" text-anchor=\"middle\" style=\"fill:var(--ink)\">Absorber</text>", 1], [145.0, "<text x=\"145.0\" y=\"309.0\" font-size=\"14\" text-anchor=\"middle\" style=\"fill:var(--ink)\">30 °C</text>", 1], [555.0, "<text x=\"555.0\" y=\"290.8\" font-size=\"14\" text-anchor=\"middle\" style=\"fill:var(--ink)\">Evaporator</text>", 1], [555.0, "<text x=\"555.0\" y=\"309.0\" font-size=\"14\" text-anchor=\"middle\" style=\"fill:var(--ink)\">−10 °C</text>", 1], [470.0, "<line x1=\"470.0\" y1=\"295.0\" x2=\"234.0\" y2=\"295.0\" style=\"stroke:var(--accent);stroke-width:2.5\" marker-end=\"url(#ar-f6-8-1b-n)\" />", 1], [352.0, "<text x=\"352.0\" y=\"286.0\" font-size=\"13\" text-anchor=\"middle\" style=\"fill:var(--ink)\">ammonia vapour</text>", 1], [555.0, "<line x1=\"555.0\" y1=\"386.0\" x2=\"555.0\" y2=\"334.0\" style=\"stroke:var(--accent);stroke-width:3\" marker-end=\"url(#ar-f6-8-1b-n)\" />", 2], [565.0, "<text x=\"565.0\" y=\"374.0\" font-size=\"14\" text-anchor=\"start\" style=\"fill:var(--accent)\" font-weight=\"700\">Q<tspan dy=\"4\" font-size=\"11\">E</tspan><tspan dy=\"-4\"> </tspan>= 10 kW in</text>", 2], [145.0, "<line x1=\"145.0\" y1=\"334.0\" x2=\"145.0\" y2=\"384.0\" style=\"stroke:var(--next);stroke-width:3\" marker-end=\"url(#ar-f6-8-1b-x)\" />", 3], [160.0, "<text x=\"160.0\" y=\"374.0\" font-size=\"14\" text-anchor=\"start\" style=\"fill:var(--next)\" font-weight=\"700\">Q<tspan dy=\"4\" font-size=\"11\">A</tspan><tspan dy=\"-4\"> </tspan> out</text>", 3], [360.0, "<text x=\"360.0\" y=\"420.0\" font-size=\"13\" text-anchor=\"middle\" style=\"fill:var(--ink)\" font-weight=\"700\">Q<tspan dy=\"4\" font-size=\"11\">C</tspan><tspan dy=\"-4\"> </tspan>+ Q<tspan dy=\"4\" font-size=\"11\">A</tspan><tspan dy=\"-4\"> </tspan>= 16.7 + 10 = 26.7 kW to the cooling water;  COP = 0.6</text>", 4]]}},
{s:2,k:'notebook',term:'Key ideas',title:'Heat instead of work',say:`Absorption swaps the compressor for an absorber, a pump and a generator. In ammonia water, ammonia is the refrigerant. The ${P('COP')} is cooling over generator heat. The ideal value needs three temperatures, in kelvin. In lithium bromide water, water is the refrigerant, chilling to five to seven degrees.`,cues:{i1:'Absorption swaps the',i2:'In ammonia water',i3:'is cooling over',i4:'The ideal value',i5:'In lithium bromide'},items:[['Absorber, pump and generator replace the compressor','i1'],['NH₃–water: ammonia is the refrigerant, water absorbs','i2'],[`COP = ${VC_s('Q','E')} ÷ (${VC_s('Q','G')} + ${VC_s('W','pump')}) ≈ ${VC_s('Q','E')} ÷ ${VC_s('Q','G')}`,'i3'],['Ideal COP: three temperatures, all in kelvin','i4'],['LiBr–water: water is the refrigerant; 5 to 7 °C','i5']],vis:(c,u,b)=>{
 const base=VC_box(10,10,620,670,{st:'#CED4DA'});
 const i1=VC_box(40,40,230,80,{fill:VC_SUN,st:ORG,sw:3,r:12})+VC_T(155,90,'generator',{fs:24,fw:800,a:'middle',fill:ORG})
  +VC_box(40,250,230,80,{fill:VC_LEAF,st:GRN,sw:3,r:12})+VC_T(155,300,'absorber',{fs:24,fw:800,a:'middle',fill:GRN})
  +VC_L(90,250,90,214,VC_DARK,4)+`<circle cx="90" cy="186" r="28" fill="#FFFFFF" stroke="${VC_STEEL}" stroke-width="4"/>`+VC_T(90,194,'P',{fs:24,fw:800,a:'middle',fill:VC_STEEL})+VC_ar(90,158,90,124,VC_DARK,4)
  +VC_ar(220,120,220,246,SLT,4)+VC_T(232,192,'weak',{fs:22,fw:700,fill:SLT})+VC_T(104,236,'strong',{fs:22,fw:700,fill:VC_DARK})
  +`<circle cx="510" cy="165" r="44" fill="#FFFFFF" stroke="${PUR}" stroke-width="4" stroke-dasharray="8 6"/>`+VC_X(510,165,32,RED)+VC_T(510,234,'no compressor',{fs:22,fw:800,a:'middle',fill:PUR});
 const i2=VC_ar(450,290,274,290,BLU,4)+VC_T(462,284,'NH₃ vapour',{fs:22,fw:800,fill:BLU})+VC_T(462,310,'from evaporator',{fs:20,fw:700,fill:BLU})
  +VC_ar(274,70,450,70,BLU,4)+VC_T(462,64,'NH₃ vapour',{fs:22,fw:800,fill:BLU})+VC_T(462,90,'to condenser',{fs:20,fw:700,fill:BLU})
  +VC_flame(155,155,.55,ORG);
 const i3=VC_box(40,380,10*24,40,{fill:BLU,st:BLU,sw:0,r:8})+VC_T(52,409,`${VC_s('Q','E')} = 10 kW`,{fs:22,fw:800,fill:'#FFFFFF'})
  +VC_box(40,430,16.7*24,40,{fill:ORG,st:ORG,sw:0,r:8})+VC_T(52,459,`${VC_s('Q','G')} = 16.7 kW`,{fs:22,fw:800,fill:'#FFFFFF'})
  +VC_T(600,442,'COP = 0.6',{fs:26,fw:800,a:'end',fill:INK});
 const i4=`<rect x="64" y="500" width="24" height="150" rx="12" fill="#FFFFFF" stroke="${VC_DARK}" stroke-width="3"/>`
  +VC_L(76,640,76,515,RED,8)
  +[[515,'T<tspan baseline-shift="sub" font-size="70%">G</tspan> 393 K',ORG],[575,'T<tspan baseline-shift="sub" font-size="70%">0</tspan> 303 K',GRN],[630,'T<tspan baseline-shift="sub" font-size="70%">E</tspan> 263 K',BLU]].map(([y,t,col])=>VC_L(92,y,112,y,col,4)+VC_T(120,y+8,t,{fs:22,fw:800,fill:col})).join('');
 const i5=VC_box(300,510,300,140,{fill:VC_ICE,st:CYN,sw:3,r:14})+`<path d="M350,540 C366,566 378,580 378,596 a28,28 0 0 1 -56,0 C322,580 334,566 350,540 Z" fill="${BLU}" fill-opacity=".75"/>`
  +VC_T(400,560,'LiBr–water',{fs:24,fw:800,fill:CYN})+VC_T(400,594,'water: 5 to 7 °C',{fs:22,fw:700,fill:INK})+VC_T(400,626,'COP about 0.7',{fs:22,fw:700,fill:INK});
 return base+g('pop',tk(c,'i1'),i1)+g('pop',tk(c,'i2'),i2)+g('pop',tk(c,'i3'),i3)+g('pop',tk(c,'i4'),i4)+g('pop',tk(c,'i5'),i5)}},
{s:2,k:'calc',term:"Worked example 2",title:"Worked example 2: ammonia-water",say:`The ammonia plant: one twenty, thirty and minus ten degrees, ten kilowatts. In kelvin, the engine part is zero point two two eight nine; the refrigerator part, six point five seven nine. Their product: an ideal ${P('COP')} of one point five one, so at least six point six four kilowatts of heat.`,cues:{fk:'The ammonia plant',k1:'the engine part',k1b:'zero point two',k2:'the refrigerator part',k2b:'six point five',k3:'Their product',k3b:'so at least'},...VC_WE2,live:[0,1,2]},
{s:2,k:'calc',term:"Worked example 2 (actual)",title:"Worked example 2: ammonia-water",say:`The real plant runs at a ${P('COP')} of zero point six, so the generator needs sixteen point seven kilowatts. The cooling water takes that plus the ten: twenty-six point seven kilowatts. That is forty percent of the ideal.`,pause:.8,cues:{fk:'The real plant',k4:'so the generator',k4b:'sixteen point seven',k5:'The cooling water',k5b:'twenty-six point',a:'That is forty'},...VC_WE2,live:[3,4],ans:['COP<tspan baseline-shift="sub" font-size="70%">max</tspan> = 1.51; Q<tspan baseline-shift="sub" font-size="70%">G</tspan> = 16.7 kW; 26.7 kW rejected (40 % of ideal)','a']},
{s:2,k:'calc',term:"Worked example 3",title:"Worked example 3: a hotel chiller",say:`Now a hotel chiller: one hundred kilowatts at five degrees, run on ninety degree exhaust water, with a thirty-five degree sink. The ideal value is one point four. At a ${P('COP')} of zero point seven, it needs one forty-two point nine kilowatts of heat.`,cues:{fk:'Now a hotel chiller',k1:'The ideal value',k1b:'is one point',k2:'At a',k2b:'it needs one'},...VC_WE3,live:[0,1]},
{s:2,k:'calc',term:"Worked example 3 (compare)",title:"Worked example 3: a hotel chiller",say:`It rejects two forty-two point nine to the cooling tower. An electric chiller, with a ${P('COP')} of four, needs twenty-five kilowatts and rejects one twenty-five. So free exhaust heat saves twenty-five kilowatts, but its tower is about twice as large.`,pause:.8,cues:{fk:'It rejects two',k3:'It rejects two',k3b:'to the cooling',k4:'An electric chiller',k4b:'needs twenty-five',a:'So free exhaust'},...VC_WE3,live:[2,3],ans:['Saves 25 kW of power; the tower is about twice as large','a']},
{s:2,k:'trap2',term:'Exam trap',title:'Exam trap!',say:'Exam trap. Never use two temperatures: evaporator over generator minus evaporator gives two point zero two, a different machine. Write all three: an engine times a refrigerator, one point five one.',cues:{x:'Exam trap',w:'Never use two',r:'Write all three'},wl:"Don't write",rl:'Write',wrong:[`COP<tspan baseline-shift="sub" font-size="70%">max</tspan> = ${VC_s('T','E')} ÷ (${VC_s('T','G')} − ${VC_s('T','E')})`,'= 263.15 ÷ 130 = 2.02'],right:[`COP<tspan baseline-shift="sub" font-size="70%">max</tspan> = (1 − ${VC_s('T','0')}/${VC_s('T','G')}) × ${VC_s('T','E')}/(${VC_s('T','0')} − ${VC_s('T','E')})`,'= 0.2289 × 6.579 = 1.51'],wv:(c,u,b)=>
 VC_res(20,20,600,56,'T<tspan baseline-shift="sub" font-size="70%">G</tspan> = 393.15 K',ORG)+VC_res(20,254,600,56,'T<tspan baseline-shift="sub" font-size="70%">E</tspan> = 263.15 K',BLU)
  +VC_ar(320,254,320,206,BLU,4)+VC_mach(320,165,38,'R',TRED)+VC_ar(320,124,320,80,ORG,4)
  +VC_T(380,158,'one Carnot fridge,',{fs:24,fw:800,fill:TRED})+VC_T(380,190,'T<tspan baseline-shift="sub" font-size="70%">E</tspan> to T<tspan baseline-shift="sub" font-size="70%">G</tspan>: 2.02',{fs:24,fw:800,fill:TRED})
  +VC_T(40,180,'no T<tspan baseline-shift="sub" font-size="70%">0</tspan>',{fs:26,fw:800,fill:TRED})
 ,rv:(c,u,b)=>VC_three({n:1})},
/* ---- recap ---- */
{s:RC,k:'recap',term:'Recap',say:`Vapor compression: throttle, then effect over work. Vapor absorption: heat drives a liquid loop. And the ideal absorption ${P('COP')} needs three temperatures, in kelvin.`,cues:{r1:'Vapor compression: throttle',r2:'Vapor absorption: heat',r3:'And the ideal'},panels:[["Vapour compression","BLU",'vcPh',['Throttling keeps h constant.',`COP = ${VC_s('q','L')} ÷ w = 4.03.`],'r1'],["Vapour absorption","ORG",'vaLoop',['A liquid loop replaces the compressor.','Heat in: COP about 0.5 to 0.7.'],'r2'],["Three temperatures","GRN",'vaThree',['An engine drives a refrigerator.','120, 30, −10 °C: COP<tspan baseline-shift="sub" font-size="70%">max</tspan> = 1.51.'],'r3']],live:[0,1,2]},
/* ---- exam practice ---- */
{s:QZ,k:'pq',term:'Question 1',lv:'U',n:1,q:"Why is the absorber cooled?",say:'Question one. Why is the absorber cooled?',cues:{k:'Question one',q:'Why is the'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 1',lv:'U',n:1,q:"Why is the absorber cooled?",say:'Dissolving ammonia in water releases heat, and a cooler solution holds more ammonia. Without cooling, absorption would stop.',cues:{a1:'Dissolving ammonia in',a2:'Without cooling'},al:[["Dissolving ammonia in water releases heat; a cooler solution holds more ammonia.",'a1'],["Without cooling, absorption would stop.",'a2']],vis:(c,u,b)=>{
 const tank=VC_box(150,110,320,250,{fill:'#FFFFFF',st:GRN,sw:4,r:18})+`<rect x="154" y="200" width="312" height="156" rx="14" fill="${VC_ICE}"/>`+VC_T(310,96,'absorber',{fs:26,fw:800,a:'middle',fill:GRN})
  +VC_ar(30,170,146,170,BLU,5)+VC_T(30,128,'NH₃',{fs:22,fw:800,fill:BLU})+VC_T(30,154,'vapour',{fs:20,fw:800,fill:BLU})
  +[[200,260],[240,300],[290,250],[340,310],[390,262],[420,320]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="10" fill="#FFFFFF" stroke="${BLU}" stroke-width="3"/>`).join('')
  +VC_T(310,345,'water absorbs it',{fs:22,fw:700,a:'middle',fill:BLU});
 const a1=VC_wave(482,260,RED,2)+VC_T(528,214,'heat',{fs:24,fw:800,fill:RED})+VC_T(524,240,'released',{fs:20,fw:700,fill:RED})
  +`<path d="M170,226 q20,-18 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0" fill="none" stroke="${CYN}" stroke-width="5"/>`
  +VC_T(310,420,'cooling water carries the heat away',{fs:22,fw:800,a:'middle',fill:CYN});
 const a2=VC_chip(80,446,'cool: holds more NH₃',GRN,22,240)+VC_chip(340,446,'hot: absorption stops',RED,22,250);
 return tank+g('pop',tk(c,'a1'),a1)+g('pop',tk(c,'a2'),a2)}},
{s:QZ,k:'pq',term:'Question 2',lv:'A',n:2,q:"In the worked example the liquid is subcooled by 5 K (h₃ = 249.0 kJ/kg). Find the new COP.",say:`Question two. In the worked example, the liquid is subcooled by five kelvin, so h three is two forty-nine. Find the new ${P('COP')}.`,cues:{k:'Question two',q:'In the worked'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 2',lv:'A',n:2,q:"In the worked example the liquid is subcooled by 5 K (h₃ = 249.0 kJ/kg). Find the new COP.",say:`The effect grows: three ninety-two point six six minus two forty-nine, so one forty-three point seven. The work is unchanged, so the ${P('COP')} is four point two five, up from four point zero three.`,cues:{fk:'The effect grows',k1:'three ninety-two point',k1b:'one forty-three point',k2:'The work is',k2b:'is four point two'},calc:{f:['q<tspan baseline-shift="sub" font-size="70%">L</tspan> = h₁ − h₄,  h₄ = h₃ = 249.0 kJ/kg','h₁ = 392.66;  w = 33.82 kJ/kg (unchanged)'],hint:'Subcooling changes only h₃ = h₄.',fk:'fk',steps:[["Refrigerating effect",["392.66 − 249.0","q<tspan baseline-shift='sub' font-size='70%'>L</tspan> = 143.7 kJ/kg"],["k1","k1b"]],["COP",["143.7 ÷ 33.82","COP = 4.25 (up from 4.03)"],["k2","k2b"]]],live:[0,1]}},
{s:QZ,k:'pq',term:'Question 3',lv:'N',n:3,q:"With the condenser at 40 °C, the COP of this R-134a cycle is 3.06 at −20 °C, 4.03 at −10 °C and 5.49 at 0 °C evaporator. Explain the trend.",say:`Question three. With the condenser at forty degrees, the ${P('COP')} is three point zero six at minus twenty, four point zero three at minus ten, and five point four nine at zero degrees. Explain the trend.`,cues:{k:'Question three',q:'With the condenser'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 3',lv:'N',n:3,q:"With the condenser at 40 °C, the COP of this R-134a cycle is 3.06 at −20 °C, 4.03 at −10 °C and 5.49 at 0 °C evaporator. Explain the trend.",say:`A colder evaporator means a lower suction pressure and a larger pressure ratio, so the work rises. The throttled mixture is also wetter, so the effect falls. Both cut the ${P('COP')}.`,cues:{a1:'A colder evaporator',a2:'The throttled mixture',a3:'Both cut the'},al:[["Colder evaporator: lower suction pressure, larger pressure ratio, so w rises.",'a1'],[`The throttled mixture is wetter, so ${VC_s('q','L')} falls.`,'a2'],["Both cut the COP.",'a3']],vis:(c,u,b)=>{
 const y0=396,k=56,bars=[[-20,3.06,80],[-10,4.03,250],[0,5.49,420]];
 const base=VC_L(40,y0,600,y0,VC_DARK,3)+bars.map(([t,v,x])=>VC_box(x,(y0-v*k).toFixed(1),120,(v*k).toFixed(1),{fill:BLU,st:BLU,sw:0,r:8,ex:'fill-opacity=".8"'})
  +VC_T(x+60,y0-v*k-12,v.toFixed(2),{fs:26,fw:800,a:'middle',fill:BLU})+VC_T(x+60,y0+30,(t<0?'−':'')+Math.abs(t)+' °C',{fs:22,fw:700,a:'middle',fill:VC_GREY})).join('')
  +VC_T(320,462,'evaporator temperature (condenser 40 °C)',{fs:22,fw:700,a:'middle',fill:VC_GREY})+VC_T(40,40,'COP',{fs:24,fw:800,fill:VC_GREY});
 const a1=VC_ar(470,40,150,40,RED,4)+VC_T(310,74,'colder: w rises',{fs:24,fw:800,a:'middle',fill:RED});
 const a2=VC_T(310,104,`and ${VC_s('q','L')} falls`,{fs:24,fw:800,a:'middle',fill:RED});
 const a3=VC_X(140,y0-3.06*k-60,16,RED);
 return base+g('pop',tk(c,'a1'),a1)+g('pop',tk(c,'a2'),a2)+g('pop',tk(c,'a3'),a3)}},
{s:LS,k:'figs',term:'Your notes',title:'For your notes',say:'Your free notes are the PDF in the description. Redraw the chart and the plant, then check every number.',cues:{t:'Your free notes',f:'Redraw the chart'},tags:[["Free notes for this lesson (PDF)", "link in the description"], ["In this lesson", "Vapour compression refrigeration cycle; Vapour absorption refrigeration"], ["Key terms and glossary", "at the end of the notes"]],figs:[["The R-134a cycle on the p-h chart", "−10 °C to 40 °C: both heat exchanges are horizontal, throttling is vertical (h₃ = h₄), and q<tspan baseline-shift='sub' font-size='70%'>L</tspan> is four times w, so COP = 4.03."], ["The ammonia-water absorption plant", "Absorber, pump and generator replace the compressor; 16.7 kW of heat at 120 °C gives 10 kW of cooling, and 26.7 kW goes to the cooling water."]],note:"Sources your free notes draw on: P. K. Nag, Engineering Thermodynamics (refrigeration cycles); Yunus A. Çengel and Michael A. Boles, Thermodynamics: An Engineering Approach (refrigeration cycles; R-134a tables); C. P. Arora, Refrigeration and Air Conditioning (vapour compression and absorption systems)."},
{s:OUT,k:'outro',term:'Outro',say:`So remember: throttling keeps the enthalpy, the ${P('COP')} is effect over work, and absorption needs three temperatures. Next time, back to the start: microscopic and macroscopic approaches. See you there!`,cues:{f:'So remember',w1:'throttling keeps the',w2:'is effect over',w3:'and absorption needs',n:'Next time',s:'See you there'},words:[['h₃ = h₄','BLU','w1'],['EFFECT ÷ WORK','ORG','w2'],['THREE TEMPERATURES','GRN','w3']],next:["NEXT TIME", "Revise from the start", "Microscopic and macroscopic approaches", "book"],end:'See you there!'}
